// src/v3/core/data-index/indexer/vault-file/worker/indexer.worker-source.ts
var hashParser = new ContentHashParser();
var tasksParser = new TasksParser();
var linksParser = new LinksParser();
var textStatsParser = new TextStatsParser();
self.onmessage = async (event) => {
  const request = event.data;
  const { id, content, file, metadata } = request;
  const context = { file, metadata };
  try {
    const [contentHash, tasks, links, textStats] = await Promise.all([
      hashParser.parse(content),
      Promise.resolve(tasksParser.parse(content, context)),
      Promise.resolve(linksParser.parse(content, context)),
      Promise.resolve(textStatsParser.parse(content, context))
    ]);
    const response = { id, contentHash, tasks, links, textStats };
    self.postMessage(response);
  } catch (error) {
    const response = {
      id,
      contentHash: "",
      tasks: [],
      links: [],
      textStats: { chars: 0, words: 0 },
      error: error instanceof Error ? error.message : String(error)
    };
    console.error("index file error", error);
    self.postMessage(response);
  }
};
